#include <iostream>
#include <vector>
#include <queue>
​
using namespace std;
​
int main() {
    int rows, cols;
    cin >> rows >> cols;
​
    vector<int> grid(rows * cols);
    queue<pair<int, int>> bfsQueue;
​
    // 读取矩阵并记录信号源
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cin >> grid[i * cols + j];
            if (grid[i * cols + j] > 0) {
                bfsQueue.emplace(i, j);
            }
        }
    }
​
    // 方向数组：上、下、左、右
    constexpr pair<int, int> directions[] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
​
    // 广度优先搜索 (BFS) 传播信号
    while (!bfsQueue.empty()) {
        auto [x, y] = bfsQueue.front();
        bfsQueue.pop();
​
        int currentSignal = grid[x * cols + y];
        if (currentSignal == 1) continue; // 1 级信号不会继续传播
​
        for (auto [dx, dy] : directions) {
            int newX = x + dx, newY = y + dy;
            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && grid[newX * cols + newY] == 0) {
                grid[newX * cols + newY] = currentSignal - 1;
                bfsQueue.emplace(newX, newY);
            }
        }
    }
​
    int targetX, targetY;
    cin >> targetX >> targetY;
    cout << grid[targetX * cols + targetY] << endl;
​
    return 0;
}
